import { Field, FieldGroup, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";

export function InputGrid() {
  return (
    <FieldGroup className="grid max-w-sm grid-cols-2">
      <Field>
        <FieldLabel>First Name</FieldLabel>
        <Input placeholder="Jordan" />
      </Field>
      <Field>
        <FieldLabel>Last Name</FieldLabel>
        <Input placeholder="Lee" />
      </Field>
    </FieldGroup>
  );
}

import { InputGrid } from "../examples/upstream/input-grid";

const Example = () => <InputGrid />;

export default Example;
